"use client";

/* Small animated pieces for React apps on obvious. The styles and motion are
   all in motion.css, and the timings are --ob-* custom properties on :root,
   so an app can retune them without touching this file.

   Toggle, Check, Matrix, Reel and PopNumber are the old names, kept so an
   app that already uses them doesn't break when it updates. */
import "./motion.css";

import {
  useEffect,
  useId,
  useLayoutEffect,
  useRef,
  useState,
  type CSSProperties,
  type ReactNode,
} from "react";

/* ---------- helpers ---------- */

export function readMs(name: string, fallback: number) {
  if (typeof window === "undefined") return fallback;
  const raw = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
  if (!raw) return fallback;
  const n = parseFloat(raw);
  if (isNaN(n)) return fallback;
  return raw.endsWith("ms") ? n : raw.endsWith("s") ? n * 1000 : n;
}

export function reduced() {
  return typeof window !== "undefined" && window.matchMedia("(prefers-reduced-motion: reduce)").matches;
}

/* ---------- AnimatedNumber ---------- */

export function AnimatedNumber({ value }: { value: string | number }) {
  const s = String(value);
  const prev = useRef(s);
  const changed = useRef(false);
  if (prev.current !== s) {
    prev.current = s;
    changed.current = true;
  }
  return (
    <span key={s} className={"ob-number" + (changed.current ? " is-animating" : "")}>
      {[...s].map((c, i) => (
        <span key={i} className="ob-number-digit" data-stagger={i > 0 ? Math.min(i, 2) : undefined}>
          {c}
        </span>
      ))}
    </span>
  );
}

/* ---------- TextSwap ---------- */

export function TextSwap({ text }: { text: string }) {
  const [shown, setShown] = useState(text);
  const ref = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (text === shown) return;
    const el = ref.current;
    if (!el || reduced()) {
      setShown(text);
      return;
    }
    el.classList.add("is-exit");
    const t = window.setTimeout(() => {
      setShown(text);
      el.classList.remove("is-exit");
      el.classList.add("is-enter-start");
      void el.offsetWidth;
      el.classList.remove("is-enter-start");
    }, readMs("--ob-text-swap-dur", 160));
    return () => window.clearTimeout(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [text]);

  return (
    <span ref={ref} className="ob-text-swap">
      {shown}
    </span>
  );
}

/* ---------- Tabs ---------- */

export type TabOption<T extends string> = { value: T; label: string; icon?: ReactNode; badge?: number };

export function Tabs<T extends string>({
  options,
  value,
  onChange,
  label,
  className,
  style,
}: {
  options: TabOption<T>[];
  value: T;
  onChange: (v: T) => void;
  label: string;
  className?: string;
  style?: CSSProperties;
}) {
  const bar = useRef<HTMLDivElement>(null);
  const pill = useRef<HTMLSpanElement>(null);
  const first = useRef(true);
  const sig = options.map((o) => o.value + ":" + o.label).join("|");

  function place(animate: boolean) {
    const b = bar.current;
    const p = pill.current;
    if (!b || !p) return;
    const t = b.querySelector<HTMLElement>('[aria-selected="true"]');
    if (!t) {
      p.style.opacity = "0";
      return;
    }
    p.style.opacity = "";
    if (!animate) p.style.transition = "none";
    p.style.transform = `translateX(${t.offsetLeft}px)`;
    p.style.width = `${t.offsetWidth}px`;
    if (!animate) {
      void p.offsetWidth;
      p.style.transition = "";
    }
    /* In a sideways-scrolling row, bring the chosen tab into view. */
    const sc = b.parentElement;
    if (animate && sc && sc.scrollWidth > sc.clientWidth) {
      const left = t.offsetLeft - sc.clientWidth / 2 + t.offsetWidth / 2;
      sc.scrollTo({ left, behavior: reduced() ? "auto" : "smooth" });
    }
  }

  useLayoutEffect(() => {
    place(!first.current);
    first.current = false;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [value, sig]);

  useEffect(() => {
    const on = () => place(false);
    const ro = new ResizeObserver(on);
    if (bar.current) ro.observe(bar.current);
    document.fonts?.ready.then(on);
    return () => ro.disconnect();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className={"ob-tabs" + (className ? " " + className : "")} role="tablist" aria-label={label} ref={bar} style={style}>
      <span className="ob-tabs-indicator" aria-hidden="true" ref={pill} />
      {options.map((o) => (
        <button
          key={o.value}
          type="button"
          role="tab"
          className="ob-tab"
          aria-selected={o.value === value}
          onClick={() => onChange(o.value)}
        >
          {o.icon !== undefined ? (
            <>
              <span className="ob-tab-icon">
                {o.icon}
                <Badge count={o.badge ?? 0} />
              </span>
              <span className="ob-tab-label">{o.label}</span>
            </>
          ) : (
            o.label
          )}
        </button>
      ))}
    </div>
  );
}

/* ---------- Badge ---------- */

export function Badge({ count }: { count: number }) {
  const last = useRef(count);
  if (count > 0) last.current = count;
  return (
    <span className="ob-badge" data-visible={count > 0} aria-hidden="true">
      <AnimatedNumber value={last.current} />
    </span>
  );
}

/* ---------- useReveal (also used to stagger list rows in) ---------- */

/* Plays the staggered entrance on the element's children, on mount and
   whenever `replay` changes. Give each child staggerStyle(i). */
export function useReveal<E extends HTMLElement>(replay?: unknown) {
  const ref = useRef<E>(null);
  useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    el.classList.add("ob-reveal-group");
    el.classList.remove("is-hiding", "is-shown");
    void el.offsetHeight;
    el.classList.add("is-shown");
  }, [replay]);
  return ref;
}

/* Delay for the nth staggered line; rows past the fold don't wait. */
export const staggerStyle = (n: number): CSSProperties => ({
  transitionDelay: `calc(var(--ob-stagger-step) * ${Math.min(n, 10)})`,
});

/* ---------- SuccessCheck ---------- */

export function SuccessCheck({ size = 44 }: { size?: number }) {
  const ref = useRef<HTMLSpanElement>(null);
  useLayoutEffect(() => {
    const wrap = ref.current;
    const path = wrap?.querySelector("path");
    if (!wrap || !path) return;
    const len = String(Math.ceil(path.getTotalLength()) + 1);
    path.style.strokeDasharray = len;
    path.style.strokeDashoffset = len;
    wrap.setAttribute("data-state", "out");
    void wrap.offsetWidth;
    wrap.setAttribute("data-state", "in");
  }, []);
  return (
    <span className="ob-success-check" data-state="out" ref={ref} aria-hidden="true">
      <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round">
        <path d="M6.5 12.5l3.6 3.6L17.5 8.5" />
      </svg>
    </span>
  );
}

/* ---------- Switch ---------- */

export function Switch({ on, onChange, label }: { on: boolean; onChange: (v: boolean) => void; label: string }) {
  const [init, setInit] = useState(false);
  return (
    <button
      type="button"
      role="switch"
      aria-checked={on}
      aria-label={label}
      className={"ob-switch" + (init ? " is-init" : "")}
      data-on={on}
      onClick={() => {
        setInit(true);
        onChange(!on);
      }}
    >
      <span className="ob-switch-thumb" />
    </button>
  );
}

/* ---------- SearchField, with the text dissolving when you clear it ---------- */

function bezier(str: string) {
  const m = String(str).match(/cubic-bezier\(([-\d.]+),\s*([-\d.]+),\s*([-\d.]+),\s*([-\d.]+)\)/);
  if (!m) return (t: number) => t;
  const [x1, y1, x2, y2] = m.slice(1).map(parseFloat);
  const cx = 3 * x1, bx = 3 * (x2 - x1) - cx, ax = 1 - cx - bx;
  const cy = 3 * y1, by = 3 * (y2 - y1) - cy, ay = 1 - cy - by;
  return (t: number) => {
    if (t <= 0) return 0;
    if (t >= 1) return 1;
    let s = t;
    for (let i = 0; i < 8; i++) {
      const dx = ((ax * s + bx) * s + cx) * s - t;
      const d = (3 * ax * s + 2 * bx) * s + cx;
      if (Math.abs(dx) < 1e-6 || d === 0) break;
      s -= dx / d;
    }
    return ((ay * s + by) * s + cy) * s;
  };
}

export function SearchField({
  value,
  onChange,
  placeholder,
  label,
}: {
  value: string;
  onChange: (v: string) => void;
  placeholder: string;
  label: string;
}) {
  const wrap = useRef<HTMLDivElement>(null);
  const input = useRef<HTMLInputElement>(null);
  const mirror = useRef<HTMLDivElement>(null);
  const phold = useRef<HTMLDivElement>(null);
  const glow = useRef<HTMLDivElement>(null);
  const [clearing, setClearing] = useState<string | null>(null);

  function buildGlow(text: string) {
    const ctx = document.createElement("canvas").getContext("2d");
    const el = input.current!;
    if (!ctx) return "";
    ctx.font = getComputedStyle(el).font;
    const dark = document.documentElement.dataset.dsMode ? document.documentElement.dataset.dsMode === "dark" : window.matchMedia("(prefers-color-scheme: dark)").matches;
    const rgb = dark ? "255,255,255" : "0,0,0";
    const w = wrap.current!.clientWidth || 280;
    const padLeft = parseFloat(getComputedStyle(el).paddingLeft) || 12;
    const spread = readMs("--ob-search-glow-spread", 1.5);
    const layers: string[] = [];
    let x = 0;
    text.split(/(\s+)/).forEach((seg) => {
      const segW = ctx.measureText(seg).width;
      if (seg.trim()) {
        const cx = padLeft + x + segW / 2;
        const hw = Math.max(segW * 0.45, 8) * spread;
        (
          [
            [0, 0.8, 7, 0.22],
            [hw * 0.45, 0.55, 8, 0.18],
            [-hw * 0.4, 0.65, 6, 0.16],
            [hw * 0.15, 0.9, 5, 0.14],
          ] as const
        ).forEach(([dx, rwm, rh, a]) => {
          const lx = (((cx + dx) / w) * 100).toFixed(2);
          layers.push(
            `radial-gradient(ellipse ${Math.max(hw * rwm, 2).toFixed(1)}px ${rh}px at ${lx}% 100%, rgba(${rgb},${a}), transparent)`
          );
        });
      }
      x += segW;
    });
    return layers.join(", ");
  }

  function clear() {
    if (clearing !== null || !value) return;
    const text = value;
    const keepFocus = document.activeElement === input.current;
    onChange("");
    if (reduced()) {
      if (keepFocus) input.current?.focus({ preventScroll: true });
      return;
    }
    setClearing(text);
    const cs = getComputedStyle(document.documentElement);
    const total = readMs("--ob-search-clear-dur", 900);
    const outDur = readMs("--ob-search-out-dur", 380);
    const inDur = readMs("--ob-search-in-dur", 380);
    const outFly = readMs("--ob-search-out-fly", 12);
    const inFly = readMs("--ob-search-in-fly", 10);
    const blur = readMs("--ob-search-blur", 2);
    const delay = readMs("--ob-search-glow-delay", 40);
    const peakAt = readMs("--ob-search-glow-peak", 0.18);
    const gOp = readMs("--ob-search-glow-opacity", 0.4);
    const easeOut = bezier(cs.getPropertyValue("--ob-search-out-ease"));
    const easeIn = bezier(cs.getPropertyValue("--ob-search-in-ease"));
    const m = mirror.current!;
    const p = phold.current!;
    const g = glow.current!;
    g.style.background = buildGlow(text);
    g.style.opacity = "0";
    p.style.transform = `translateY(-${inFly}px)`;
    p.style.opacity = "0.9";
    p.style.filter = `blur(${blur}px)`;

    const t0 = performance.now();
    const tick = (now: number) => {
      const el = now - t0;
      const eo = easeOut(Math.min(1, el / outDur));
      m.style.transform = `translateY(${(eo * outFly).toFixed(1)}px)`;
      m.style.opacity = (1 - eo).toFixed(3);
      m.style.filter = `blur(${(eo * blur).toFixed(1)}px)`;
      const ei = easeIn(Math.min(1, el / inDur));
      p.style.transform = `translateY(${(-inFly + ei * inFly).toFixed(1)}px)`;
      p.style.opacity = (0.9 + ei * 0.1).toFixed(3);
      p.style.filter = `blur(${(blur - ei * blur).toFixed(1)}px)`;
      let k = 0;
      if (el > delay) {
        const gp = Math.min(1, (el - delay) / Math.max(1, total - delay));
        k = gp < peakAt ? gp / peakAt : 1 - (gp - peakAt) / (1 - peakAt);
      }
      g.style.opacity = (k * gOp).toFixed(3);
      if (el < total) {
        requestAnimationFrame(tick);
      } else {
        m.style.cssText = "";
        p.style.cssText = "";
        g.style.opacity = "0";
        g.style.background = "";
        setClearing(null);
        if (keepFocus) requestAnimationFrame(() => input.current?.focus({ preventScroll: true }));
      }
    };
    requestAnimationFrame(tick);
  }

  const keep = (e: React.SyntheticEvent) => {
    if (document.activeElement === input.current) e.preventDefault();
  };
  const shown = clearing ?? value;

  return (
    <div
      ref={wrap}
      className={"ob-search" + (value ? " has-value" : "") + (clearing !== null ? " is-clearing" : "")}
    >
      <svg className="ob-search-icon" width="18" height="18" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" aria-hidden="true">
        <circle cx="9" cy="9" r="6" />
        <path d="M13.5 13.5L17 17" />
      </svg>
      <input
        ref={input}
        type="search"
        enterKeyHint="search"
        aria-label={label}
        value={value}
        onChange={(e) => onChange(e.target.value)}
      />
      <div className="ob-search-mirror" ref={mirror} aria-hidden="true">
        {shown.replace(/ /g, "\u00a0")}
      </div>
      <div className="ob-search-placeholder" ref={phold} aria-hidden="true">
        {placeholder}
      </div>
      <div className="ob-search-glow" ref={glow} aria-hidden="true" />
      <button type="button" className="ob-search-clear" aria-label="Clear search" onPointerDown={keep} onMouseDown={keep} onClick={clear}>
        <svg width="10" height="10" viewBox="0 0 10 10" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round">
          <path d="M2 2l6 6M8 2L2 8" />
        </svg>
      </button>
    </div>
  );
}

/* ---------- Checkbox ---------- */

export function Checkbox({
  checked,
  onChange,
  label,
}: {
  checked: boolean;
  onChange: (v: boolean) => void;
  label: string;
}) {
  return (
    <button
      type="button"
      role="checkbox"
      aria-checked={checked}
      aria-label={label}
      className="ob-checkbox"
      onClick={() => onChange(!checked)}
    >
      <svg width="12" height="12" viewBox="0 0 10.1668 10.1668" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
        <path d="M1 5.52L3.92 9.17L9.17 1" pathLength={1} />
      </svg>
    </button>
  );
}

/* ---------- IconSwap (plus or copy, to a tick) ---------- */

export function IconSwap({ state, icon = "plus" }: { state: "a" | "b"; icon?: "plus" | "copy" }) {
  return (
    <span className="ob-icon-swap" data-state={state}>
      <span className="ob-icon-swap-icon" data-icon="a">
        <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round">
          {icon === "copy" ? (
            <>
              <rect x="5.5" y="5.5" width="8" height="8" rx="2" />
              <path d="M10.5 5.5V4a1.5 1.5 0 0 0-1.5-1.5H4A1.5 1.5 0 0 0 2.5 4v5A1.5 1.5 0 0 0 4 10.5h1.5" />
            </>
          ) : (
            <path d="M8 3v10M3 8h10" />
          )}
        </svg>
      </span>
      <span className="ob-icon-swap-icon" data-icon="b">
        <svg width="14" height="14" viewBox="0 0 16 16" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
          <path d="M3 8.5l3.2 3.2L13 4.8" />
        </svg>
      </span>
    </span>
  );
}

/* ---------- DotLoader ---------- */

const CORNERS = [0, 3, 12, 15];
const RING = [1, 2, 7, 11, 14, 13, 8, 4];

export function DotLoader({ variant = "orbit" }: { variant?: "orbit" | "scan" | "twinkle" | "pulse" }) {
  const cycle = 1200;
  return (
    <span className="ob-dot-loader" data-variant={variant} aria-hidden="true">
      {Array.from({ length: 16 }, (_, idx) => {
        if (CORNERS.includes(idx)) return <i key={idx} className="is-gap" />;
        if (variant === "scan") return <i key={idx} style={{ ["--d" as string]: Math.round((idx % 4) * (cycle / 10)) } as CSSProperties} />;
        const k = RING.indexOf(idx);
        if (k === -1) return <i key={idx} style={{ animation: "none" }} />;
        return <i key={idx} style={{ ["--d" as string]: Math.round(k * (cycle / 8)) } as CSSProperties} />;
      })}
    </span>
  );
}

/* ---------- Odometer ---------- */

const CELLS = Array.from({ length: 40 }, (_, i) => i % 10);

/* Each cell is 1/40 of the strip, so positions are percentages and stay right
   if the cell size changes with the screen. */
const at = (n: number) => `translateY(${(-n / CELLS.length) * 100}%)`;

function OdometerCol({ digit, index, roll }: { digit: number; index: number; roll: boolean }) {
  const strip = useRef<HTMLDivElement>(null);
  const blur = useRef<SVGFEGaussianBlurElement>(null);
  const prev = useRef<number | null>(null);
  const id = "odometer" + useId().replace(/[^a-zA-Z0-9]/g, "");

  useLayoutEffect(() => {
    const el = strip.current;
    if (!el) return;

    if (prev.current === null || reduced()) {
      el.style.transition = "none";
      el.style.transform = at(digit);
      prev.current = digit;
      return;
    }
    if (prev.current === digit) return;

    const from = prev.current;
    prev.current = digit;
    /* A spin goes round twice before landing. A roll moves forward to the next
       digit, the way a clock turns over, so 9 to 0 is one step. */
    const to = roll ? from + ((digit - from + 10) % 10) : 20 + digit;
    const dur = roll ? readMs("--ob-odometer-roll-dur", 600) : readMs("--ob-odometer-dur", 1400);
    const delay = index * readMs("--ob-odometer-stagger", 90);
    const maxBlur = readMs("--ob-odometer-blur", 3) * (roll ? 0.5 : 1);

    el.style.transition = "none";
    el.style.transform = at(from);
    void el.offsetWidth;
    el.style.transition = `transform ${dur}ms var(--ob-odometer-ease) ${delay}ms`;
    el.style.transform = at(to);
    el.style.filter = `url(#${id})`;

    let raf = 0;
    const start = performance.now() + delay;
    const tick = (now: number) => {
      const t = Math.min(1, Math.max(0, (now - start) / dur));
      const y = maxBlur * (1 - t) * (1 - t);
      blur.current?.setAttribute("stdDeviation", `0 ${y.toFixed(2)}`);
      if (t < 1) raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);

    const done = window.setTimeout(() => {
      el.style.transition = "none";
      el.style.transform = at(digit);
      el.style.filter = "";
    }, dur + delay + 40);

    return () => {
      cancelAnimationFrame(raf);
      window.clearTimeout(done);
    };
  }, [digit, index, id, roll]);

  return (
    <span className="ob-odometer-col">
      <svg width="0" height="0" style={{ position: "absolute" }} aria-hidden="true" focusable="false">
        <defs>
          <filter id={id} x="-20%" y="-50%" width="140%" height="200%">
            <feGaussianBlur ref={blur} in="SourceGraphic" stdDeviation="0 0" />
          </filter>
        </defs>
      </svg>
      <div className="ob-odometer-strip" ref={strip}>
        {CELLS.map((d, i) => (
          <span key={i} className="ob-odometer-digit">
            {d}
          </span>
        ))}
      </div>
    </span>
  );
}

/* cell sets the digit height in px; leave it out to size it from
   --ob-odometer-cell in CSS. pad keeps leading zeros, so 5 past reads 05.
   roll steps to the next digit instead of spinning, for things that tick
   like a clock. */
export function Odometer({ value, cell, pad = 0, roll = false }: { value: number; cell?: number; pad?: number; roll?: boolean }) {
  const digits = String(Math.max(0, Math.floor(value))).padStart(pad, "0").split("").map(Number);
  return (
    <span
      className="ob-odometer"
      role="img"
      aria-label={String(value)}
      style={cell ? ({ ["--ob-odometer-cell" as string]: `${cell}px` } as CSSProperties) : undefined}
    >
      {digits.map((d, i) => (
        <OdometerCol key={digits.length - i} digit={d} index={i} roll={roll} />
      ))}
    </span>
  );
}

/* ---------- Old names ---------- */

export const PopNumber = AnimatedNumber;
export const Toggle = Switch;
export const Check = Checkbox;
export const Matrix = DotLoader;
export const Reel = Odometer;

/* Styles and motion for the pieces in motion.tsx. Everything they need is
   here: colours, sizes and timing come from the --ds-* tokens, and the knobs
   below are set on :root at zero specificity so an app can retune any of them. */

:where(:root) {
  --ob-text-swap-dur: 160ms;
  --ob-stagger-step: 40ms;
  --ob-tabs-dur: 320ms;
  --ob-number-dur: 420ms;
  --ob-switch-dur: 260ms;
  --ob-check-dur: 320ms;
  --ob-success-dur: 560ms;
  --ob-dot-loader-lap: 1200ms;
  --ob-odometer-cell: 1.2em;
  --ob-odometer-dur: 1400ms;
  --ob-odometer-roll-dur: 600ms;
  --ob-odometer-stagger: 90ms;
  --ob-odometer-blur: 3;
  --ob-odometer-ease: cubic-bezier(0.2, 0.9, 0.25, 1);
  --ob-search-clear-dur: 900ms;
  --ob-search-out-dur: 380ms;
  --ob-search-in-dur: 380ms;
  --ob-search-out-fly: 12;
  --ob-search-in-fly: 10;
  --ob-search-blur: 2;
  --ob-search-out-ease: cubic-bezier(0.4, 0, 1, 1);
  --ob-search-in-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --ob-search-glow-delay: 40ms;
  --ob-search-glow-peak: 0.18;
  --ob-search-glow-opacity: 0.4;
  --ob-search-glow-spread: 1.5;
}

:where(.ob-tab, .ob-switch, .ob-checkbox, .ob-search-clear) {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
  touch-action: manipulation;
}

/* ---------- AnimatedNumber ---------- */

.ob-number { display: inline-flex; font-variant-numeric: tabular-nums; }
.ob-number-digit { display: inline-block; }
.ob-number.is-animating .ob-number-digit {
  animation: ob-number-in var(--ob-number-dur) var(--ds-ease-out) both;
}
.ob-number.is-animating .ob-number-digit[data-stagger="1"] { animation-delay: 40ms; }
.ob-number.is-animating .ob-number-digit[data-stagger="2"] { animation-delay: 80ms; }
@keyframes ob-number-in {
  from { opacity: 0; translate: 0 0.45em; filter: blur(2px); }
  to { opacity: 1; translate: 0; filter: none; }
}

/* ---------- TextSwap ---------- */

.ob-text-swap {
  display: inline-block;
  transition:
    opacity var(--ob-text-swap-dur) var(--ds-ease-out),
    translate var(--ob-text-swap-dur) var(--ds-ease-out),
    filter var(--ob-text-swap-dur) var(--ds-ease-out);
}
.ob-text-swap.is-exit { opacity: 0; translate: 0 -0.3em; filter: blur(2px); }
.ob-text-swap.is-enter-start { opacity: 0; translate: 0 0.3em; filter: blur(2px); transition: none; }

/* ---------- Tabs ---------- */

.ob-tabs {
  position: relative;
  display: inline-flex;
  gap: 2px;
  padding: 3px;
  border-radius: var(--ds-radius-full);
  background: var(--ds-color-bg-alt);
}
.ob-tabs-indicator {
  position: absolute;
  top: 3px;
  bottom: 3px;
  left: 0;
  border-radius: var(--ds-radius-full);
  background: var(--ds-color-surface);
  box-shadow: var(--ds-shadow-sm);
  transition:
    transform var(--ob-tabs-dur) var(--ds-ease-out),
    width var(--ob-tabs-dur) var(--ds-ease-out),
    opacity var(--ds-duration-fast) var(--ds-ease-out);
}
.ob-tab {
  position: relative;
  z-index: 1;
  display: inline-flex;
  align-items: center;
  gap: var(--ds-space-2xs);
  min-height: var(--ds-control-height-sm);
  padding: 0 var(--ds-space-sm);
  border-radius: var(--ds-radius-full);
  color: var(--ds-color-text-muted);
  font-size: var(--ds-type-ui-size);
  font-weight: var(--ds-type-ui-weight);
  white-space: nowrap;
  transition: color var(--ds-duration-fast) var(--ds-ease-out);
}
.ob-tab:hover,
.ob-tab[aria-selected="true"] { color: var(--ds-color-text); }

/* Tabs with an icon: the badge hangs off the icon's corner. */
.ob-tab-icon { position: relative; display: inline-grid; }
.ob-tab-icon svg { display: block; }
.ob-tab-icon .ob-badge { position: absolute; top: -7px; right: -11px; }

/* ---------- Badge ---------- */
/* The same badge as obvious/css/components/badge.css, so a React app
   doesn't need the CSS layer as well. */

.ob-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 18px;
  height: 18px;
  padding: 0 var(--ds-space-2xs);
  border-radius: var(--ds-radius-full);
  background: var(--ob-badge-bg, var(--ds-color-danger));
  color: var(--ds-color-accent-contrast);
  font-size: var(--ds-text-micro);
  font-weight: var(--ds-weight-bold);
  line-height: 1;
  font-variant-numeric: tabular-nums;
  box-shadow: 0 0 0 2px var(--ds-color-bg);
  pointer-events: none;
  transition: scale var(--ds-duration-slow) var(--ds-ease-spring), opacity var(--ds-duration-fast) var(--ds-ease-out);
}
.ob-badge[data-visible="false"] {
  scale: 0;
  opacity: 0;
  transition: scale var(--ds-duration-fast) var(--ds-ease-in), opacity var(--ds-duration-fast) var(--ds-ease-in);
}

/* ---------- useReveal and staggerStyle ---------- */

.ob-reveal-group > * {
  opacity: 0;
  translate: 0 8px;
  transition: opacity var(--ds-duration-base) var(--ds-ease-out), translate var(--ds-duration-base) var(--ds-ease-out);
}
.ob-reveal-group.is-shown > * { opacity: 1; translate: 0; }
.ob-reveal-group.is-hiding > * { opacity: 0; translate: 0; transition-delay: 0s !important; }

/* ---------- SuccessCheck ---------- */

.ob-success-check { display: inline-grid; place-items: center; color: var(--ds-color-success); }
.ob-success-check svg { display: block; }
.ob-success-check[data-state="in"] { animation: ob-success-pop var(--ob-success-dur) var(--ds-ease-spring) both; }
.ob-success-check[data-state="in"] path {
  stroke-dashoffset: 0 !important;
  transition: stroke-dashoffset var(--ob-success-dur) var(--ds-ease-out) 80ms;
}
@keyframes ob-success-pop {
  from { scale: 0.6; opacity: 0; }
  to { scale: 1; opacity: 1; }
}

/* ---------- Switch ---------- */

.ob-switch {
  width: 44px;
  height: 26px;
  padding: 2px;
  flex: none;
  display: inline-flex;
  align-items: center;
  border-radius: var(--ds-radius-full);
  background: var(--ds-color-border-strong);
  transition: background-color var(--ob-switch-dur) var(--ds-ease-out);
}
.ob-switch[data-on="true"] { background: var(--ds-color-success); }
.ob-switch-thumb {
  display: block;
  width: 22px;
  height: 22px;
  border-radius: var(--ds-radius-full);
  background: var(--ds-color-surface);
  box-shadow: var(--ds-shadow-sm);
}
.ob-switch[data-on="true"] .ob-switch-thumb { translate: 18px 0; }
/* No slide on first paint, only once someone has used it. */
.ob-switch.is-init .ob-switch-thumb { transition: translate var(--ob-switch-dur) var(--ds-ease-spring); }

/* ---------- Checkbox ---------- */

.ob-checkbox {
  width: 28px;
  height: 28px;
  flex: none;
  display: grid;
  place-items: center;
  border-radius: var(--ds-radius-full);
  border: var(--ds-border-thick) solid var(--ds-color-border-strong);
  background: var(--ds-color-surface);
  color: var(--ds-color-accent-contrast);
  transition:
    background-color var(--ob-check-dur) var(--ds-ease-out),
    border-color var(--ob-check-dur) var(--ds-ease-out),
    scale var(--ds-duration-fast) var(--ds-ease-out);
}
.ob-checkbox:active { scale: 0.92; }
.ob-checkbox svg { width: 13px; height: 13px; }
.ob-checkbox path {
  stroke-dasharray: 1;
  stroke-dashoffset: 1;
  transition: stroke-dashoffset var(--ob-check-dur) var(--ds-ease-out);
}
.ob-checkbox[aria-checked="true"] { background: var(--ds-color-success); border-color: var(--ds-color-success); }
.ob-checkbox[aria-checked="true"] path { stroke-dashoffset: 0; transition-delay: 60ms; }

/* ---------- IconSwap ---------- */

.ob-icon-swap { display: inline-grid; place-items: center; }
.ob-icon-swap-icon {
  grid-area: 1 / 1;
  display: grid;
  place-items: center;
  transition:
    opacity var(--ds-duration-base) var(--ds-ease-out),
    scale var(--ds-duration-base) var(--ds-ease-spring),
    filter var(--ds-duration-base) var(--ds-ease-out);
}
.ob-icon-swap[data-state="a"] .ob-icon-swap-icon[data-icon="b"],
.ob-icon-swap[data-state="b"] .ob-icon-swap-icon[data-icon="a"] { opacity: 0; scale: 0.5; filter: blur(2px); }

/* ---------- DotLoader ---------- */

.ob-dot-loader {
  display: inline-grid;
  grid-template-columns: repeat(4, 3px);
  gap: 2px;
  color: var(--ds-color-text);
}
.ob-dot-loader i {
  width: 3px;
  height: 3px;
  border-radius: var(--ds-radius-full);
  background: currentColor;
  opacity: 0.18;
  animation: ob-dot-chase var(--ob-dot-loader-lap) linear infinite;
  animation-delay: calc(var(--d, 0) * 1ms - var(--ob-dot-loader-lap));
}
.ob-dot-loader i.is-gap { visibility: hidden; animation: none; }
.ob-dot-loader[data-variant="scan"] i { animation-name: ob-dot-scan; }
.ob-dot-loader[data-variant="twinkle"] i { animation-name: ob-dot-twinkle; animation-duration: calc(var(--ob-dot-loader-lap) * 1.6); }
.ob-dot-loader[data-variant="pulse"] i { animation-name: ob-dot-pulse; animation-delay: 0s; }
@keyframes ob-dot-chase { 0% { opacity: 1; } 60%, 100% { opacity: 0.18; } }
@keyframes ob-dot-scan { 0%, 100% { opacity: 0.18; } 25% { opacity: 1; } }
@keyframes ob-dot-twinkle { 0%, 100% { opacity: 0.18; scale: 0.8; } 15% { opacity: 1; scale: 1.15; } 40% { opacity: 0.18; scale: 1; } }
@keyframes ob-dot-pulse { 0%, 100% { opacity: 0.25; } 50% { opacity: 1; } }

/* ---------- Odometer ---------- */

.ob-odometer { display: inline-flex; font-variant-numeric: tabular-nums; line-height: 1; }
.ob-odometer-col { position: relative; height: var(--ob-odometer-cell); overflow: hidden; }
.ob-odometer-strip { display: flex; flex-direction: column; will-change: transform; }
.ob-odometer-digit { height: var(--ob-odometer-cell); line-height: var(--ob-odometer-cell); text-align: center; }

/* ---------- SearchField ---------- */

.ob-search {
  position: relative;
  height: var(--ds-control-height-lg);
  flex: 1;
  min-width: 0;
  border-radius: var(--ds-radius-md);
  background: var(--ds-color-bg-alt);
  color: var(--ds-color-text);
  transition: box-shadow var(--ds-duration-fast) var(--ds-ease-out);
}
.ob-search:focus-within { box-shadow: inset 0 0 0 var(--ds-border-thick) var(--ds-color-accent); }
.ob-search > input {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  margin: 0;
  border: 0;
  outline: none;
  background: transparent;
  border-radius: inherit;
  font: inherit;
  color: inherit;
  -webkit-appearance: none;
  appearance: none;
}
.ob-search > input::-webkit-search-cancel-button { -webkit-appearance: none; display: none; }
.ob-search > input,
.ob-search-mirror,
.ob-search-placeholder { padding: 0 44px 0 42px; font-size: max(16px, var(--ds-type-ui-size)); }
.ob-search-mirror,
.ob-search-placeholder {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  white-space: nowrap;
  overflow: hidden;
  pointer-events: none;
}
.ob-search-placeholder { color: var(--ds-color-text-muted); }
.ob-search-mirror { visibility: hidden; }
.ob-search.has-value .ob-search-placeholder { visibility: hidden; }
.ob-search.is-clearing > input { color: transparent; }
.ob-search.is-clearing .ob-search-mirror,
.ob-search.is-clearing .ob-search-placeholder { visibility: visible; }
.ob-search-glow { position: absolute; inset: 0; border-radius: inherit; opacity: 0; pointer-events: none; }
.ob-search-icon {
  position: absolute;
  left: 14px;
  top: 50%;
  translate: 0 -50%;
  z-index: 1;
  color: var(--ds-color-text-muted);
  pointer-events: none;
}
.ob-search-clear {
  position: absolute;
  right: 9px;
  top: 50%;
  z-index: 2;
  width: 28px;
  height: 28px;
  display: grid;
  place-items: center;
  border-radius: var(--ds-radius-full);
  background: color-mix(in srgb, var(--ds-color-text-muted) 45%, transparent);
  color: var(--ds-color-surface);
  translate: 0 -50%;
  opacity: 0;
  scale: 0.6;
  pointer-events: none;
  transition: opacity var(--ds-duration-fast) var(--ds-ease-out), scale var(--ds-duration-base) var(--ds-ease-spring);
}
/* The visible circle is 28px, but the tap area reaches 44px. */
.ob-search-clear::before { content: ""; position: absolute; inset: -8px; }
.ob-search.has-value .ob-search-clear { opacity: 1; scale: 1; pointer-events: auto; }

@media (prefers-color-scheme: dark) {
  :root:not([data-ds-mode="light"]) .ob-search-glow { mix-blend-mode: screen; }
}
:root[data-ds-mode="dark"] .ob-search-glow { mix-blend-mode: screen; }

@media (prefers-reduced-motion: reduce) {
  .ob-number.is-animating .ob-number-digit,
  .ob-success-check[data-state="in"],
  .ob-dot-loader i { animation: none; }
  .ob-dot-loader i { opacity: 0.6; }
  .ob-text-swap, .ob-tabs-indicator, .ob-switch-thumb, .ob-checkbox, .ob-checkbox path,
  .ob-icon-swap-icon, .ob-reveal-group > *, .ob-badge, .ob-search, .ob-search-clear { transition: none !important; }
}
